@import "@fontsource-variable/hanken-grotesk";
@import "@fontsource-variable/source-code-pro";

/* Light (faithful): grey-white paper, pure white for cards and nav pills, black ink for text,
   buttons and every hovered/active state, one olive-gold band. Dark stone under photos. */
:root {
  --background: oklch(0.97 0 0);
  --foreground: oklch(0 0 0);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0 0 0);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0 0 0);
  --primary: oklch(0 0 0);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(1 0 0);
  --secondary-foreground: oklch(0 0 0);
  --muted: oklch(0.905 0 0);
  --muted-foreground: oklch(0.52 0 0);
  --accent: oklch(0.93 0 0);
  --accent-foreground: oklch(0 0 0);
  --destructive: oklch(0.55 0.2 27);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.8 0 0);
  --input: oklch(0 0 0);
  --ring: oklch(0 0 0);
  --highlight: oklch(0.76 0.087 106);
  --highlight-foreground: oklch(0 0 0);
  --glow: oklch(0.36 0.012 95);
  --chart-1: oklch(0.76 0.087 106);
  --chart-2: oklch(0 0 0);
  --chart-3: oklch(0.52 0 0);
  --chart-4: oklch(0.8 0 0);
  --chart-5: oklch(0.36 0.012 95);
  --sidebar: oklch(1 0 0);
  --sidebar-foreground: oklch(0 0 0);
  --sidebar-primary: oklch(0 0 0);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.93 0 0);
  --sidebar-accent-foreground: oklch(0 0 0);
  --sidebar-border: oklch(0.8 0 0);
  --sidebar-ring: oklch(0 0 0);

  --typeface-body: "Hanken Grotesk Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Hanken Grotesk Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: "Source Code Pro Variable", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.3rem;
  --page-width: 81.25rem;
  --page-gutter: 0.5rem;
  --section-y: 3rem;
}

@media (min-width: 64rem) {
  :root {
    --page-gutter: 1.5rem;
    --section-y: 4.25rem;
  }
}

/* Dark (sibling): the same idea inverted: near-black paper, raised charcoal cards, paper ink
   and paper buttons, the same olive-gold, a little brighter. */
.dark {
  --background: oklch(0.16 0 0);
  --foreground: oklch(0.96 0 0);
  --card: oklch(0.22 0 0);
  --card-foreground: oklch(0.96 0 0);
  --popover: oklch(0.22 0 0);
  --popover-foreground: oklch(0.96 0 0);
  --primary: oklch(0.96 0 0);
  --primary-foreground: oklch(0.12 0 0);
  --secondary: oklch(0.22 0 0);
  --secondary-foreground: oklch(0.96 0 0);
  --muted: oklch(0.27 0 0);
  --muted-foreground: oklch(0.68 0 0);
  --accent: oklch(0.27 0 0);
  --accent-foreground: oklch(0.96 0 0);
  --destructive: oklch(0.65 0.19 27);
  --destructive-foreground: oklch(0.96 0 0);
  --border: oklch(0.96 0 0 / 22%);
  --input: oklch(0.96 0 0);
  --ring: oklch(0.96 0 0);
  --highlight: oklch(0.79 0.09 106);
  --highlight-foreground: oklch(0.12 0 0);
  --glow: oklch(0.3 0.012 95);
  --chart-1: oklch(0.79 0.09 106);
  --chart-2: oklch(0.96 0 0);
  --chart-3: oklch(0.68 0 0);
  --chart-4: oklch(0.45 0 0);
  --chart-5: oklch(0.3 0.012 95);
  --sidebar: oklch(0.2 0 0);
  --sidebar-foreground: oklch(0.96 0 0);
  --sidebar-primary: oklch(0.96 0 0);
  --sidebar-primary-foreground: oklch(0.12 0 0);
  --sidebar-accent: oklch(0.27 0 0);
  --sidebar-accent-foreground: oklch(0.96 0 0);
  --sidebar-border: oklch(0.96 0 0 / 22%);
  --sidebar-ring: oklch(0.96 0 0);
}
